-- 组装物料清单导入(bs_asm_bom,单表 doc 模式)
-- 来源:金蝶 BOM 引出列表 引出列表_BOM单_20261019174847.xlsx(sheet「列表数据」)
-- 生成器:tools/archive/_asm-bom-import-20261030/gen-asm-bom.mjs(勿手改本文件,改生成器后重跑)
-- 范围:plang 未作废行的 distinct dm(244 个在产产品)∩ Excel 父产品(817 个) = 236 个产品
--       在产但 Excel 无 BOM 的 8 个产品不导(属正常):A-32-13, A-32-17, A-32-26, B-65-04, C-95-32, D-01-18, S092-2, T042-6
-- 选块:每产品一张 BOM;优先 默认BOM='是';否则取 编码 _V 后缀数字最大者;被跳过的多版本块 2 个
-- 字段:工序='组装';版本号=编码 _V 后缀;来源='金蝶BOM引出列表_20261019174847';行序=块内 1..n;
--       标准用量=ROUND(用量:分子/用量:分母,4)(分母空/0 按 1);损耗量=0;计量单位先空、由 bs_inv 回填
-- 幂等:开头仅按 来源 删除本脚本导入的行,再全量插入;可重复执行
-- 预期:1085 行 / 236 张单据 / 236 个产品
SET NOCOUNT ON;
IF OBJECT_ID('dbo.bs_asm_bom') IS NULL
BEGIN
    RAISERROR(N'[FAIL] dbo.bs_asm_bom 不存在:先执行 tools/migrate-asm-bom-20261030.sql 建表', 16, 1);
    RETURN;
END;

-- 1) 幂等清理:只动本来源的行
DELETE FROM dbo.bs_asm_bom WHERE 来源 = N'金蝶BOM引出列表_20261019174847';

-- 2) 插入(每条 200 行以内,共 6 批)
GO

GO

